begin; do $$ declare m uuid; tok uuid; tok2 uuid; u int; begin select id,coalesce((payload->>'collection_update_no')::int,0) into m,u from public.rr_customer_chat_messages_v9433 where payload->>'source'='DIRECT_MARKET_WINDOW' and sender_kind='STAFF' and archived_at is null and chat_id in(select id from public.rr_customer_chat_v9433 where data_mode='TEST' and relation_kind='DIRECT_CUSTOMER') limit 1; if m is null then raise exception 'TEST fixture missing'; end if; update public.rr_customer_chat_messages_v9433 set payload=jsonb_set(payload,'{collection_update_no}',to_jsonb(u+1)) where id=m; select dispatch_token into tok from public.rr_chat_push_outbox_v61 where message_id=m and processed_at is null and target_url like '%open=collection'; if tok is null then raise exception 'Update did not enqueue collection push'; end if; update public.rr_customer_chat_messages_v9433 set payload=payload where id=m; select dispatch_token into tok2 from public.rr_chat_push_outbox_v61 where message_id=m; if tok2<>tok then raise exception 'No-op replay triggered push'; end if; end $$; rollback;
